Document 初始文本为 `ab`。InsertCommand 保存 Document 引用、位置与文本；位置超过当前长度时 execute 抛出 std::out_of_range，且在插入前完成检查。Editor 只记录成功命令。Document 的寿命覆盖所有命令；本题只分析位置越界异常，假设分配及历史栈扩容成功。补全三个空，先执行 Insert(2,`X`) 并撤销，再执行 Insert(9,`Y`)。
```cpp
#include <memory>
#include <string>
#include <utility>
#include <vector>
#include <stdexcept>
struct Document { std::string text = "ab"; };
struct ICommand {
    /* ① */
    virtual void execute() = 0;
    virtual void undo() = 0;
};
struct InsertCommand : ICommand {
    Document& document;
    std::size_t position;
    std::string inserted;
    InsertCommand(Document& d, std::size_t p, std::string value)
        : document(d), position(p), inserted(std::move(value)) {}
    void execute() override {
        if (position > document.text.size()) throw std::out_of_range("position");
        document.text.insert(position, inserted);
    }
    void undo() override { document.text.erase(position, inserted.size()); }
};
class Editor {
    std::vector<std::unique_ptr<ICommand>> history_;
public:
    void run(std::unique_ptr<ICommand> cmd) {
        /* ② */
        /* ③ */
    }
    void undoLast() {
        if (history_.empty()) return;
        history_.back()->undo();
        history_.pop_back();
    }
};
